function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 2000) return 's needs 1 to 2000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  const counts = new Map();
  for (const c of s) counts.set(c, (counts.get(c) ?? 0) + 1);
  if ([...counts.values()].filter(v => v % 2 === 1).length > 1) return 's must be rearrangeable into a palindrome (at most one letter with an odd count).';
  return null;
}

