function minMovesToMakePalindrome(s) {
  const chars = s.split('');
  let moves = 0;
  let left = 0;
  let right = chars.length - 1;

  while (left < right) {
    let match = right;
    while (chars[match] !== chars[left]) {
      match--;
    }
    if (match === left) {
      const lone = chars[left];
      chars[left] = chars[left + 1];
      chars[left + 1] = lone;
      moves++;
      continue;
    }
    const [moved] = chars.splice(match, 1);
    chars.splice(right, 0, moved);
    moves += right - match;
    left++;
    right--;
  }
  return moves;
}

