function minMovesToMakePalindrome(s) {
  const isPalindrome = t => t === t.split('').reverse().join('');
  const seen = new Set([s]);
  let frontier = [s];
  for (let steps = 0; frontier.length; steps++) {
    const next = [];
    for (const t of frontier) {
      if (isPalindrome(t)) return steps;
      for (let i = 0; i + 1 < t.length; i++) {
        const u = t.slice(0, i) + t[i + 1] + t[i] + t.slice(i + 2);
        if (!seen.has(u)) { seen.add(u); next.push(u); }
      }
    }
    frontier = next;
  }
  return -1;
}

