function generate(rand, size) {
  const large = size === 'large';
  const letters = 1 + Math.floor(rand() * (large ? 26 : 4));
  const half = large ? 999 : Math.floor(rand() * 5);
  const middle = rand() < 0.5;
  const pick = () => String.fromCharCode(97 + Math.floor(rand() * letters));
  const chars = [];
  for (let i = 0; i < half; i++) { const c = pick(); chars.push(c, c); }
  if (middle || chars.length === 0) chars.push(pick());
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
